BEGIN READ ONLY;SET LOCAL search_path='';
WITH targets AS (SELECT c.oid,n.nspname||'.'||c.relname name FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE (n.nspname,c.relname) IN (('public','ai_budget_accounts'),('public','ai_usage_ledger'),('public','whatsapp_inbound_jobs'),('public','knowledge_sources'),('public','billing_subscriptions'),('public','billing_plan_versions'),('public','billing_catalog_revision'),('private','billing_service_grants'),('private','billing_service_offers'),('private','billing_service_order_offers'),('private','ai_plan_budget_policies'))), policies AS (SELECT t.name,p.polname,p.polcmd,p.polpermissive,(SELECT jsonb_agg(CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r) END ORDER BY CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r) END) FROM unnest(p.polroles) r) roles,pg_get_expr(p.polqual,p.polrelid) using_expression,pg_get_expr(p.polwithcheck,p.polrelid) check_expression FROM targets t JOIN pg_policy p ON p.polrelid=t.oid), column_acl AS (SELECT t.name,a.attname,coalesce(r.rolname,'PUBLIC') grantee,x.privilege_type,x.is_grantable FROM targets t JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum>0 AND NOT a.attisdropped CROSS JOIN LATERAL aclexplode(a.attacl) x LEFT JOIN pg_roles r ON r.oid=x.grantee) SELECT jsonb_build_object('policies',(SELECT jsonb_agg(to_jsonb(policies) ORDER BY name,polname) FROM policies),'column_acl',(SELECT jsonb_agg(to_jsonb(column_acl) ORDER BY name,attname,grantee,privilege_type,is_grantable) FROM column_acl));
COMMIT;
